-- Storage keys (relative to the private `hotdog-images` bucket), never URLs.
-- Signed read URLs are generated by the API right before a response is sent.
--
-- Expand/contract (zero-downtime): `original_image_path` replaces `image_path`.
-- During the deploy window the previous app version still writes `image_path`, so a trigger
-- keeps both columns in sync. TODO(next release): drop `image_path`, the trigger and function.
alter table public.hotdog_classifications
  add column original_image_path text;

update public.hotdog_classifications
  set original_image_path = image_path
  where original_image_path is null;

alter table public.hotdog_classifications
  alter column image_path drop not null;

create or replace function public.sync_hotdog_classification_image_path()
returns trigger
language plpgsql
as $$
begin
  new.original_image_path := coalesce(new.original_image_path, new.image_path);
  new.image_path := coalesce(new.image_path, new.original_image_path);
  return new;
end;
$$;

-- BEFORE triggers run before NOT NULL / UNIQUE checks, so old-version inserts stay valid.
create trigger hotdog_classifications_sync_image_path
before insert or update on public.hotdog_classifications
for each row execute function public.sync_hotdog_classification_image_path();

alter table public.hotdog_classifications
  alter column original_image_path set not null,
  add constraint hotdog_classifications_original_image_path_key unique (original_image_path);

-- Small preview for the history list. Nullable: older rows only have the original.
alter table public.hotdog_classifications
  add column thumbnail_image_path text;
